REPLACE INTO projects (id, status, title, summary, product_type, engagement, contribution_kind, contribution, technologies, tasks, problem, completed, links, featured, experience_id, also_types, audiences) VALUES ('crm-falcon', 'public', 'CRM Falcon Force', 'A CRM for Falcon Force Academy covering clients, staff, salaries, expenses, income, and payment orders.', 'dashboard', NULL, 'built', 'Built the CRM for Falcon Force Academy.', '["React","Node.js","Express","MongoDB"]', '["Add clients, staff, and salaries.","Record expenses and income.","Generate a PDF of income and expenses.","Track payment orders."]', NULL, 'The CRM keeps Falcon Force Academy clients, staff, salaries, expenses, income, and payment orders.', '[]', 1, NULL, '[]', '["home","fullstack"]');
UPDATE experiences SET bullets = '["Developed and maintained websites, web applications, and Android and iOS mobile applications.","Worked on frontend interfaces, backend functionality, databases, and API integrations.","Tested applications, resolved technical issues, and supported deployments, updates, and maintenance.","Collaborated with management, marketing, and operations teams on business requirements.","Managed the mobile development team.","Made architecture decisions.","Planned sprints.","Reviewed code.","Defined the technical roadmap."]' WHERE id = 'exp-ulegendary';
UPDATE posts SET title='Products in the software portfolio', excerpt='The mobile apps and the CRM that are described in both the project list and the resume notes.', tags='["Flutter","React","Product"]', body='[{"type":"paragraph","text":"These are the products named in both places. The case studies stay with what those two sources agree on."},{"type":"heading","text":"Mobile"},{"type":"list","items":["PropTelli — a Flutter mobile application for Casa Key Real Estate, with Google Maps, push notifications, offline storage, a supporting CRM, and the PropTelli website.","Choose n Fly — hotel booking for travel agents.","Malankara Devotional — a devotional app for the Syro Malankara Catholic Church, with prayer times, church locations, and daily prayers."]},{"type":"heading","text":"Website and marketing"},{"type":"list","items":["Tripzza — the website for Tripzza Holidays, at tripzza.com.","Falcon Force Academy — the website for the martial arts and fitness school in Sharjah, at falconforceacademy.com.","ChooseMy Fresh — the website, its social media platforms, and its website SEO."]},{"type":"heading","text":"Dashboard"},{"type":"list","items":["CRM Falcon Force — the CRM for Falcon Force Academy. It records clients, staff, salaries, expenses, and income, generates a PDF of income and expenses, and tracks payment orders. Built with React, Node.js, Express, and MongoDB."]}]' WHERE track='software' AND slug='products-in-the-software-portfolio';
UPDATE posts SET title='Website work I can describe', excerpt='Tripzza, Falcon Force Academy, and CRM Falcon Force are published websites and a CRM. ChooseMy Fresh and the PropTelli website stay from the employment notes.', tags='["Websites","CRM"]', body='[{"type":"paragraph","text":"CRM Falcon Force is the CRM for Falcon Force Academy. It records clients, staff, salaries, expenses, and income, generates a PDF of income and expenses, and tracks payment orders, using React, Node.js, Express, and MongoDB."},{"type":"paragraph","text":"I built the Tripzza website at tripzza.com and the Falcon Force Academy website at falconforceacademy.com. ChooseMy Fresh is the website I created, alongside its social media and website SEO. The PropTelli website sits with the Casa Key Real Estate role, at proptelli.com."}]' WHERE track='marketing' AND slug='web-storefronts-in-the-portfolio';

UPDATE posts SET title='What the marketing page covers', excerpt='ChooseMy Fresh covers a website, social media, and website SEO. Advertising campaigns are not listed.', tags='["Social media","Websites"]', body='[{"type":"paragraph","text":"The digital marketing page includes ChooseMy Fresh: I created the website, managed its social media platforms, and worked on its website SEO. The skills list also includes SEO, Meta Ads, Google Ads, and WhatsApp automation."},{"type":"paragraph","text":"I also work on social content and website updates. Development skills sit under that work because they help with landing pages, tracking snippets, and fixes on the site itself."}]' WHERE track='marketing' AND slug='services-on-the-marketing-side';
UPDATE posts SET title='Checking a site before changing it', excerpt='Analytics, Search Console, Tag Manager, and Semrush sit with the other marketing skills.', tags='["Analytics","Websites"]', body='[{"type":"paragraph","text":"Google Analytics, Search Console, Tag Manager, and Semrush are listed with the marketing skills. I use them to check a site before changing it."},{"type":"paragraph","text":"The published website SEO work is ChooseMy Fresh. The skills list also includes SEO, Meta Ads, Google Ads, and WhatsApp automation."}]' WHERE track='marketing' AND slug='reading-a-site-before-changing-it';

UPDATE experiences SET bullets = '["Worked on a Flutter ecommerce application.","Used GetX and Provider."]', technologies = '["Flutter","GetX","Provider"]' WHERE id = 'exp-slr';
UPDATE posts SET title='Flutter and React on the same desk', excerpt='The employment record covers Flutter apps in Kochi and Thrissur, and web and mobile work in Dubai.', tags='["Flutter","React"]', body='[{"type":"paragraph","text":"ULEGENDARY DIGITAL in Dubai is listed as Web & Mobile App Developer from January 2026. The end date is still to confirm. The work there covers websites, web applications, and Android and iOS mobile applications, including frontend, backend, databases, and API integrations."},{"type":"paragraph","text":"Casa Key Real Estate in Dubai was Mobile Application Developer from October 2024 to December 2025. That role built the PropTelli mobile application in Flutter, with Google Maps, push notifications, offline storage, and Android and iOS releases. The same role created the supporting CRM and the PropTelli website. Globosoft in Kochi was Flutter Developer from August 2023 to October 2024, maintaining 10+ mobile applications. SLR SHOPPEE PVT LTD in Thrissur was Flutter Developer from March 2022 to March 2023. That role was work on a Flutter ecommerce application, using GetX and Provider."},{"type":"heading","text":"Roles"},{"type":"list","items":["ULEGENDARY DIGITAL — Web & Mobile App Developer, Dubai, from January 2026","Casa Key Real Estate — Mobile Application Developer, Dubai, October 2024 to December 2025","Globosoft — Flutter Developer, Kochi, August 2023 to October 2024","SLR SHOPPEE PVT LTD — Flutter Developer, Thrissur, March 2022 to March 2023"]},{"type":"paragraph","text":"Luminar Technohub in Kochi was a Flutter Development Course from March 2023 to July 2023. It is listed under training."}]' WHERE track='software' AND slug='flutter-and-react-on-the-same-desk';
